import React from 'react';
import { useNavigate } from 'react-router-dom';

const MainMenu = () => {
  const navigate = useNavigate();

  const games = [
    {
      id: 'ti-albert',
      name: 'Ti Albert',
      description: 'Ti-Albert party game for 4-15 players',
      available: true,
      path: '/ti-albert-setup'
    }
    
  ];

  const handleGameSelect = (game) => {
    if (game.available && game.path) {
      navigate(game.path);
    }
  };

  const handleJoinGame = () => {
    navigate('/join');
  };

  return (
    <div className="container">
      <div className="card">
        <h1 className="title">Ti-Albert</h1>
        <p className="subtitle">Party Games Hub</p>
        
        <div style={{ marginBottom: '30px' }}>
          <h2 style={{ 
            fontSize: '1.3rem', 
            marginBottom: '20px', 
            color: '#4a5568',
            textAlign: 'center'
          }}>
            Select a Game
          </h2>
          
          {games.map((game) => (
            <button
              key={game.id}
              className={`button ${!game.available ? 'secondary' : ''}`}
              onClick={() => handleGameSelect(game)}
              disabled={!game.available}
              style={{
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                padding: '20px',
                marginBottom: '15px',
                textAlign: 'center',
                position: 'relative'
              }}
            >
              <div style={{ 
                fontSize: '1.3rem', 
                fontWeight: 'bold',
                marginBottom: '5px'
              }}>
                {game.name}
              </div>
              <div style={{ 
                fontSize: '0.9rem', 
                opacity: 0.8,
                fontWeight: 'normal',
                textTransform: 'none',
                letterSpacing: 'normal'
              }}>
                {game.description}
              </div>
              {!game.available && (
                <div style={{
                  position: 'absolute',
                  top: '10px',
                  right: '10px',
                  background: '#ed8936',
                  color: 'white',
                  padding: '4px 8px',
                  borderRadius: '4px',
                  fontSize: '0.7rem',
                  fontWeight: 'bold'
                }}>
                  SOON
                </div>
              )}
            </button>
          ))}
        </div>

        <div style={{ 
          borderTop: '2px solid #e2e8f0', 
          paddingTop: '25px',
          marginTop: '25px'
        }}>
          <h2 style={{ 
            fontSize: '1.3rem', 
            marginBottom: '20px', 
            color: '#4a5568',
            textAlign: 'center'
          }}>
            Or Join Existing Game
          </h2>
          
          <button
            className="button secondary"
            onClick={handleJoinGame}
            style={{
              fontSize: '1.2rem',
              padding: '18px'
            }}
          >
            🎮 Join Game
          </button>
        </div>

        <div style={{ 
          marginTop: '30px', 
          textAlign: 'center',
          fontSize: '0.9rem',
          color: '#718096'
        }}>
          <p>Create games or join with friends locally</p>
          <p style={{ marginTop: '5px' }}>
            Connect to the same WiFi network
          </p>
        </div>
      </div>
    </div>
  );
};

export default MainMenu;
